code.DataFrame:
$events = DataFrame::fromCsv('events.csv');
$dims = DataFrame::fromCsv('dims.csv');

$rows = $events
    ->groupBy(['key'])
    ->summarise([
        'n' => fn (Table $g) => $g->nrow(),
        'sum_x' => fn (Table $g) => array_sum(array_filter($g->column('x'), fn ($v) => $v !== null)),
    ])
    ->collect()->nrow();

